<?php/** * Descripción de la clase: Generada por Doctrine Generate * * @author    : Generada por Doctrine Generate * @copyright Copyright (c) 2013 xetid */class SubordinacionModel extends ZendExt_Model{    /**     * Constructor de la clase     */    public function __construct()    {        parent::ZendExt_Model();    }    /**     * Descripción del método: Buscar todos los hijos de una estructura     *     * @author    : Ing. Javier Limonta Neyra     * @modified  : Ing. Yoandry Borges Acosta     *     * @param int $idPadre     * @param bool $tipoSubordinacion     *     * @return array, Devuelve un arreglo con todos los hijos de una estructura especificada     * @copyright Copyright (c) 2013 xetid     */    public function dameHijos($idPadre, $tipoSubordinacion = FALSE)    {        $sqlTipoSubordinacion = $tipoSubordinacion ? ' AND s.idnomsubordinacion = ' . $tipoSubordinacion : '';        $sqlWhere            = ($idPadre) ? "s.idpadre = $idPadre AND s.idhijo <> s.idpadre" : 's.idhijo = s.idpadre';        $mg = Doctrine_Manager::getInstance();        $conn = $mg->getCurrentConnection();        $subConsulta            = "(SELECT COUNT(idsubordinacion)					   	FROM mod_estructuracomp.dat_subordinacion					  	WHERE idpadre<> idhijo AND idpadre = s.idhijo) > 0";        $query = "SELECT s.idhijo as idestructura, s.idnomsubordinacion,  ($subConsulta) as leaf,                  CASE                    WHEN e.denominacion<>'' THEN				              ( SELECT i.icono				                FROM mod_estructuracomp.nom_concepto cc				                INNER JOIN mod_estructuracomp.nom_icono i ON (cc.idicono = i.idicono)				                WHERE cc.idconcepto = e.idconcepto				              )                    WHEN op.denominacion<>'' THEN				              ( SELECT i.icono				                FROM mod_estructuracomp.nom_concepto cc				                INNER JOIN mod_estructuracomp.nom_icono i ON (cc.idicono = i.idicono)				                WHERE cc.idconcepto = op.idconcepto				              )                    WHEN nomcargo.denominacion <> '' THEN				              ( SELECT i.icono				                FROM mod_estructuracomp.nom_concepto cc				                INNER JOIN mod_estructuracomp.nom_icono i ON (cc.idicono = i.idicono)				                WHERE cc.idconcepto = 7				              )				              WHEN medio.idicono IS NOT NULL THEN				              ( SELECT i.icono				                FROM mod_estructuracomp.nom_icono i				                WHERE i.idicono = medio.idicono				              )				             WHEN nommedio.denominacion <> '' THEN				              ( SELECT i.icono				                FROM mod_estructuracomp.nom_concepto cc				                INNER JOIN mod_estructuracomp.nom_icono i ON (cc.idicono = i.idicono)				                WHERE cc.idconcepto = 9				              )                  END AS icono,                  CASE                    WHEN e.denominacion<>'' THEN e.idconcepto                    WHEN op.denominacion<>'' THEN op.idconcepto                    WHEN nomcargo.denominacion <> '' THEN 7				             WHEN nommedio.denominacion <> '' THEN 9                  END AS idconcepto,                  CASE                    WHEN e.denominacion <> ''         THEN e.denominacion                    WHEN nomcargo.denominacion <> ''  THEN nomcargo.denominacion                    WHEN nommedio.denominacion <> ''  THEN nommedio.denominacion                    WHEN op.denominacion <> ''        THEN op.denominacion                  END AS denominacion,                  CASE                    WHEN e.abreviatura <> ''        THEN e.abreviatura                    WHEN nomcargo.abreviatura <> '' THEN nomcargo.abreviatura                    WHEN op.abreviatura <> ''       THEN op.abreviatura                  END AS abreviatura                  FROM mod_estructuracomp.dat_subordinacion s                  LEFT JOIN mod_estructuracomp.dat_estructura e     ON e.idestructura = s.idhijo AND e.idestado = 0                  LEFT JOIN mod_estructuracomp.dat_estructuraop op  ON op.idestructuraop = s.idhijo AND op.idestado = 0                  LEFT JOIN mod_estructuracomp.dat_cargo cargo      ON cargo.idcargo = s.idhijo AND cargo.idestado = 0                  LEFT JOIN mod_estructuracomp.nom_cargo nomcargo   ON cargo.idnomcargo = nomcargo.idnomcargo                  LEFT JOIN mod_estructuracomp.dat_cargocivil cc    ON cargo.idcargo = cc.idcargo                  LEFT JOIN mod_estructuracomp.dat_cargomilitar cm  ON cargo.idcargo = cm.idcargo                  LEFT JOIN mod_estructuracomp.dat_medio medio      ON medio.idmedio = s.idhijo AND medio.idestado = 0                  LEFT JOIN mod_datosmaestros.nom_indicador nommedio   ON medio.idnommedio = nommedio.idindicador                  WHERE ($sqlWhere $sqlTipoSubordinacion AND (nommedio.denominacion<>'' or nomcargo.denominacion<>''                  or e.denominacion<>'' or op.denominacion<>''))";        $result = $conn->fetchAll($query);        return $result;    }    /**     * Descripción del método: Buscar todos los padres de una estructura     *     * @author    : Ing. Javier Limonta Neyra     * @modified  : Ing. Yoandry Borges Acosta     * @modified  : Ing. Osvaldo Gonzalez Ortiz     *     * @param bool|int $idHijo     * @param bool     $idSubordinacion     * @param bool     $aExcluir     * @param bool     $esPadre     *     * @return mixed, Devuelve todos los elementos de una estructura especificada que sean padres     * @copyright Copyright (c) 2013 xetid     */    public function dameDatos($idHijo = FALSE, $idSubordinacion = FALSE, $aExcluir = FALSE, $esPadre = TRUE)    {        $sqlWhere = "1 = 1";        if ($idHijo != FALSE) {            $whereHijos = $this->constructWhere($idHijo, $esPadre, $aExcluir);            $sqlWhere = ($idHijo) ? $whereHijos . " AND idhijo <> idpadre" : "idhijo = idpadre ";        }        $whereSubordinacion = "idnomsubordinacion = $idSubordinacion";        if (is_array($idSubordinacion)) {            $whereSubordinacion = "idnomsubordinacion IN (" . implode(',', $idSubordinacion) . ")";        }        $sqlTipoSub = $idSubordinacion ? " AND " . $whereSubordinacion : '';        $q = Doctrine_Query::create();        $result = $q->select('idpadre,idhijo')->from('DatSubordinacion')->where($sqlWhere . $sqlTipoSub)                    ->setHydrationMode(Doctrine :: HYDRATE_ARRAY)->execute();        /** @noinspection PhpTraditionalSyntaxArrayLiteralInspection */        $datos = array();        $valor = ($esPadre) ? 'idhijo' : 'idpadre';        foreach ($result as $value) {            /** @noinspection PhpUndefinedFieldInspection */            $datos = array_merge($datos, $this->integrator->metadatos->DameEstructura($value[$valor]));        }        return $datos;    }    /**     * @param $idHijo     * @param $esPadre     *     * @param $aExcluir     *     * @return string     */    private function constructWhere($idHijo, $esPadre, $aExcluir)    {        $whereHijos = ($esPadre) ? "idpadre = $idHijo" : "idhijo =$idHijo ";        $valor = ($esPadre) ? "idhijo" : "idpadre";        if (is_array($idHijo)) {            if ($esPadre) {                $whereHijos = "idpadre IN (" . implode(',', $idHijo) . ")";            } else {                $whereHijos = "idhijo IN (" . implode(',', $idHijo) . ")";            }            if (is_array($aExcluir)) {                $whereHijos .= " AND $valor NOT IN (" . implode(',', $aExcluir) . ") ";            }            return $whereHijos;        }        return $whereHijos;    }    /**     * Obtener el parent_path     *     * @param $idEstructura     *     * @param $idsub     *     * @author Ing. Daymel Machado Cabrera     * @return mixed     */    public function getParentPath($idEstructura, $idsub)    {        $query = Doctrine_Query::create();        $result = $query->select('ds.parent_path as camino')            ->from('DatSubordinacion ds')            ->where("ds.idhijo = ? AND ds.idnomsubordinacion = ?", array($idEstructura, $idsub))            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)->execute();        return $result[0]['camino'];    }    public function getChidLtree($idEstructura, $idsub = FALSE)    {        $where = (!$idsub) ? " 1 = 1" : "idnomsubordinacion = $idsub";        $parentPath = $this->getParentPath($idEstructura, $idsub);        $conn = Doctrine_Manager::getInstance()->getCurrentConnection();        //Como estaba        /*$sql = "SELECT DISTINCT idpadre,idhijo,idnomsubordinacion,parent_path,public.nlevel(parent_path) as nivel                FROM mod_estructuracomp.dat_subordinacion                WHERE parent_path OPERATOR (public.<@) '$parentPath' AND $where AND idhijo <> $idEstructura order by                 nivel";        $resultado = $conn->fetchAll($sql);*/        $sql = "SELECT DISTINCT idpadre,idhijo,idnomsubordinacion,parent_path,public.nlevel(parent_path) as nivel                FROM mod_estructuracomp.dat_subordinacion                WHERE $where AND ((idpadre = $idEstructura) and (idhijo <> $idEstructura)) order by                 nivel";        $resultado = $conn->fetchAll($sql);        $datos = [];        foreach ($resultado as $value) {            /** @noinspection PhpUndefinedFieldInspection */            $datos = array_merge($datos, $this->integrator->metadatos->DameEstructura($value['idhijo']));        }        return $datos;    }    public function getFatherLtree($idEstructura, $idsub = FALSE)    {        $where = (!$idsub) ? " 1 = 1" : "idnomsubordinacion = $idsub";        $parentPath = $this->getParentPath($idEstructura, $idsub);        $conn = Doctrine_Manager::getInstance()->getCurrentConnection();        $sql = "SELECT DISTINCT idpadre,idhijo,idnomsubordinacion,parent_path,public.nlevel(parent_path) as nivel                FROM mod_estructuracomp.dat_subordinacion                WHERE parent_path OPERATOR (public.@>) '$parentPath' AND $where AND idhijo <> $idEstructura order by                 nivel";        $resultado = $conn->fetchAll($sql);        $datos = [];        foreach ($resultado as $value) {            /** @noinspection PhpUndefinedFieldInspection */            $datos = array_merge($datos, $this->integrator->metadatos->DameEstructura($value['idhijo']));        }        return $datos;    }}